/**
 * Opens a session for the caller on a machine, as the caller's account, and returns once it
 * is ready. With `desktop` the session has a desktop; without, it offers terminals, programs,
 * files, ports, sound, devices, printers and privilege approvals. The account is created if
 * the caller has none yet. Requires `fleet:machines.login` on the machine.
 *
 * Fails with:
 * - `MACHINE_OFFLINE` when the machine is not connected;
 * - `FEATURE_UNAVAILABLE` when the machine does not offer sessions, or with `desktop`,
 *   desktops;
 * - `USER_HAS_SESSION` when the account already has a session on the machine, which
 *   `metadata.sessionId` names; connect to it instead;
 * - `USER_NOT_FOUND`, `USER_NOT_ALLOWED`, `ACCOUNT_EXPIRED` or `PAM_PERMISSION_DENIED` when
 *   the machine refuses the account, such as while it has not received the account yet or a
 *   local account uses its name; `PAM_PERMISSION_DENIED` carries the machine's message in
 *   `metadata.pamMessage`;
 * - `SESSION_CONFLICT` with `desktop` when the account has a graphical session on the
 *   machine that Fleet did not open;
 * - `DISPLAY_UNAVAILABLE` or `SESSION_START_FAILED` when the machine could not start it;
 * - `MACHINE_TIMEOUT` when the machine did not answer in time. The session may still open;
 *   list the sessions before trying again.
 * @summary Open a session
 */
export const CreateSessionBody = CreateSessionRequest;

/**
 * @summary Get a session
 */
export const getSessionPathSessionIdMax = 40;

export const getSessionPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const GetSessionParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(getSessionPathSessionIdMax)
    .regex(getSessionPathSessionIdRegExp),
});

/**
 * Ends the session in order: its applications are asked to exit and get a grace period
 * before the session is terminated. Returns once the session is closed. Closing a closed
 * session succeeds.
 *
 * The owner may close their own session; closing another member's requires
 * `fleet:sessions.manage`. Fails with `MACHINE_OFFLINE` or `MACHINE_TIMEOUT` as
 * for opening a session.
 * @summary Close a session
 */
export const closeSessionPathSessionIdMax = 40;

export const closeSessionPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const CloseSessionParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(closeSessionPathSessionIdMax)
    .regex(closeSessionPathSessionIdRegExp),
});

/**
 * Ends the session at once, killing every process in it. Returns once the session is
 * closed. Terminating a closed session succeeds.
 *
 * The owner may terminate their own session; terminating another member's requires
 * `fleet:sessions.manage`. Fails with `MACHINE_OFFLINE` or `MACHINE_TIMEOUT` as
 * for opening a session.
 * @summary Terminate a session
 */
export const terminateSessionPathSessionIdMax = 40;

export const terminateSessionPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const TerminateSessionParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(terminateSessionPathSessionIdMax)
    .regex(terminateSessionPathSessionIdRegExp),
});

/**
 * Returns the viewers connected to the session, in the order they connected.
 * @summary List the viewers of a session
 */
export const listSessionViewersPathSessionIdMax = 40;

export const listSessionViewersPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const ListSessionViewersParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(listSessionViewersPathSessionIdMax)
    .regex(listSessionViewersPathSessionIdRegExp),
});

/**
 * Disconnects the viewer from the session; the session goes on. The viewer can connect
 * again only with a new ticket.
 *
 * The owner of the session may disconnect its viewers; otherwise this requires
 * `fleet:sessions.manage`.
 * @summary Disconnect a viewer
 */
export const deleteViewerPathSessionIdMax = 40;

export const deleteViewerPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const DeleteViewerParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(deleteViewerPathSessionIdMax)
    .regex(deleteViewerPathSessionIdRegExp),
  connectionId: zod.int().min(1),
});

/**
 * Issues a single-use ticket that admits one viewer connection with the given public key to
 * the session. It is valid for 60 seconds.
 *
 * The owner of a session may operate it. Viewing another member's session requires
 * `fleet:sessions.view`, which admits watching only, or
 * `fleet:sessions.control`, which also admits operating it. Each further capability
 * of the session — file transfer, the clipboard, terminals and programs, port forwarding,
 * devices and audio, printing, SSH agent forwarding, approving privilege requests and
 * reading logs — is granted only with its permission; a viewer that may only watch gets
 * none of them. A ticket may ask for less: to watch only, or for some of the capabilities.
 *
 * A request made by a browser binds the ticket to its `Origin`, which the WebSocket
 * connection must carry too.
 *
 * Fails with:
 * - `SESSION_CLOSED` when the session has ended;
 * - `SESSION_ACCESS_DENIED` when the caller may not view the session.
 * @summary Create a viewer ticket
 */
export const createViewerTicketPathSessionIdMax = 40;

export const createViewerTicketPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const CreateViewerTicketParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(createViewerTicketPathSessionIdMax)
    .regex(createViewerTicketPathSessionIdRegExp),
});

export const CreateViewerTicketBody = CreateViewerTicketRequest;
